const express = require('express');
const diagnostics_channel = require('node:diagnostics_channel');
const { AsyncLocalStorage } = require('node:async_hooks');
const { verifySessionToken } = require('./auth');

const app = express();
const requestStorage = new AsyncLocalStorage();
const amqpChannel = diagnostics_channel.channel('amqp:publish:envelope');

const messageRegistry = new Map();

amqpChannel.subscribe((envelope) => {
  const store = requestStorage.getStore();
  messageRegistry.set(envelope.correlationId, {
    tenantId: store?.tenantId,
    queue: envelope.queue,
    payload: envelope.payload,
    publishedAt: Date.now()
  });
});

app.use(verifySessionToken);
app.use((req, res, next) => {
  requestStorage.run({ tenantId: req.session.tenantId }, next);
});

app.get('/api/monitoring/messages/:correlationId', (req, res) => {
  const msg = messageRegistry.get(req.params.correlationId);
  if (!msg) {
    return res.status(404).json({ error: 'Message not found in trace cache' });
  }

  // Ensure caller belongs to the tenant that produced the message
  if (msg.tenantId !== req.session.tenantId) {
    return res.status(403).json({ error: 'Access denied: message belongs to another tenant' });
  }

  res.json(msg);
});

app.listen(9103);
